@=========================== AC ===========================@
.equ AC_BASE, 0x42002000 @ (Analog Comparators) 
    .equ AC_CTRLA, AC_BASE + 0x0 @ (Control A) 
        .equ AC_SWRST_Shift, 0   @ bitWidth 1 (Software Reset)  
        .equ AC_ENABLE_Shift, 1   @ bitWidth 1 (Enable)  
 
    .equ AC_CTRLB, AC_BASE + 0x1 @ (Control B) 
        .equ AC_START0_Shift, 0   @ bitWidth 1 (Comparator 0 Start Comparison)  
        .equ AC_START1_Shift, 1   @ bitWidth 1 (Comparator 1 Start Comparison)  
 
    .equ AC_EVCTRL, AC_BASE + 0x2 @ (Event Control) 
        .equ AC_COMPEO0_Shift, 0   @ bitWidth 1 (Comparator 0 Event Output Enable)  
        .equ AC_COMPEO1_Shift, 1   @ bitWidth 1 (Comparator 1 Event Output Enable)  
        .equ AC_WINEO0_Shift, 4   @ bitWidth 1 (Window 0 Event Output Enable)  
        .equ AC_COMPEI0_Shift, 8   @ bitWidth 1 (Comparator 0 Event Input Enable)  
        .equ AC_COMPEI1_Shift, 9   @ bitWidth 1 (Comparator 1 Event Input Enable)  
        .equ AC_INVEI0_Shift, 12   @ bitWidth 1 (Comparator 0 Input Event Invert Enable)  
        .equ AC_INVEI1_Shift, 13   @ bitWidth 1 (Comparator 1 Input Event Invert Enable)  
 
    .equ AC_INTENCLR, AC_BASE + 0x4 @ (Interrupt Enable Clear) 
        .equ AC_COMP0_Shift, 0   @ bitWidth 1 (Comparator 0 Interrupt Enable)  
        .equ AC_COMP1_Shift, 1   @ bitWidth 1 (Comparator 1 Interrupt Enable)  
        .equ AC_WIN0_Shift, 4   @ bitWidth 1 (Window 0 Interrupt Enable)  
 
    .equ AC_INTENSET, AC_BASE + 0x5 @ (Interrupt Enable Set) 
        .equ AC_COMP0_Shift, 0   @ bitWidth 1 (Comparator 0 Interrupt Enable)  
        .equ AC_COMP1_Shift, 1   @ bitWidth 1 (Comparator 1 Interrupt Enable)  
        .equ AC_WIN0_Shift, 4   @ bitWidth 1 (Window 0 Interrupt Enable)  
 
    .equ AC_INTFLAG, AC_BASE + 0x6 @ (Interrupt Flag Status and Clear) 
        .equ AC_COMP0_Shift, 0   @ bitWidth 1 (Comparator 0)  
        .equ AC_COMP1_Shift, 1   @ bitWidth 1 (Comparator 1)  
        .equ AC_WIN0_Shift, 4   @ bitWidth 1 (Window 0)  
 
    .equ AC_STATUSA, AC_BASE + 0x7 @ (Status A) 
        .equ AC_STATE0_Shift, 0   @ bitWidth 1 (Comparator 0 Current State)  
        .equ AC_STATE1_Shift, 1   @ bitWidth 1 (Comparator 1 Current State)  
        .equ AC_WSTATE0_Shift, 4   @ bitWidth 2 (Window 0 Current State)  
 
    .equ AC_STATUSB, AC_BASE + 0x8 @ (Status B) 
        .equ AC_READY0_Shift, 0   @ bitWidth 1 (Comparator 0 Ready)  
        .equ AC_READY1_Shift, 1   @ bitWidth 1 (Comparator 1 Ready)  
 
    .equ AC_DBGCTRL, AC_BASE + 0x9 @ (Debug Control) 
        .equ AC_DBGRUN_Shift, 0   @ bitWidth 1 (Debug Run)  
 
    .equ AC_WINCTRL, AC_BASE + 0xA @ (Window Control) 
        .equ AC_WEN0_Shift, 0   @ bitWidth 1 (Window 0 Mode Enable)  
        .equ AC_WINTSEL0_Shift, 1   @ bitWidth 2 (Window 0 Interrupt Selection)  
 
    .equ AC_SCALER[%s], AC_BASE + 0xC @ (Scaler n) 
        .equ AC_VALUE_Shift, 0   @ bitWidth 6 (Scaler Value)  
 
    .equ AC_COMPCTRL[%s], AC_BASE + 0x10 @ (Comparator Control n) 
        .equ AC_ENABLE_Shift, 1   @ bitWidth 1 (Enable)  
        .equ AC_SINGLE_Shift, 2   @ bitWidth 1 (Single-Shot Mode)  
        .equ AC_INTSEL_Shift, 3   @ bitWidth 2 (Interrupt Selection)  
        .equ AC_RUNSTDBY_Shift, 6   @ bitWidth 1 (Run in Standby)  
        .equ AC_MUXNEG_Shift, 8   @ bitWidth 3 (Negative Input Mux Selection)  
        .equ AC_MUXPOS_Shift, 12   @ bitWidth 3 (Positive Input Mux Selection)  
        .equ AC_SWAP_Shift, 15   @ bitWidth 1 (Swap Inputs and Invert)  
        .equ AC_SPEED_Shift, 16   @ bitWidth 2 (Speed Selection)  
        .equ AC_HYSTEN_Shift, 19   @ bitWidth 1 (Hysteresis Enable)  
        .equ AC_HYST_Shift, 20   @ bitWidth 2 (Hysteresis Level)  
        .equ AC_FLEN_Shift, 24   @ bitWidth 3 (Filter Length)  
        .equ AC_OUT_Shift, 28   @ bitWidth 2 (Output)  
 
    .equ AC_SYNCBUSY, AC_BASE + 0x20 @ (Synchronization Busy) 
        .equ AC_SWRST_Shift, 0   @ bitWidth 1 (Software Reset Synchronization Busy)  
        .equ AC_ENABLE_Shift, 1   @ bitWidth 1 (Enable Synchronization Busy)  
        .equ AC_WINCTRL_Shift, 2   @ bitWidth 1 (WINCTRL Synchronization Busy)  
        .equ AC_COMPCTRL0_Shift, 3   @ bitWidth 1 (COMPCTRL 0 Synchronization Busy)  
        .equ AC_COMPCTRL1_Shift, 4   @ bitWidth 1 (COMPCTRL 1 Synchronization Busy)  
 
    .equ AC_CALIB, AC_BASE + 0x24 @ (Calibration) 
        .equ AC_BIAS0_Shift, 0   @ bitWidth 2 (COMP0/1 Bias Scaling)  
 

