    .equ ICM_CTRL, ICM_BASE + 0x4 @ (Control) 
        .equ ICM_ENABLE_Shift, 0   @ bitWidth 1 (ICM Enable)  
        .equ ICM_DISABLE_Shift, 1   @ bitWidth 1 (ICM Disable Register)  
        .equ ICM_SWRST_Shift, 2   @ bitWidth 1 (Software Reset)  
        .equ ICM_REHASH_Shift, 4   @ bitWidth 4 (Recompute Internal Hash)  
        .equ ICM_RMDIS_Shift, 8   @ bitWidth 4 (Region Monitoring Disable)  
        .equ ICM_RMEN_Shift, 12   @ bitWidth 4 (Region Monitoring Enable)  
 
    .equ ICM_SR, ICM_BASE + 0x8 @ (Status) 
        .equ ICM_ENABLE_Shift, 0   @ bitWidth 1 (ICM Controller Enable Register)  
        .equ ICM_RAWRMDIS_Shift, 8   @ bitWidth 4 (RAW Region Monitoring Disabled Status)  
        .equ ICM_RMDIS_Shift, 12   @ bitWidth 4 (Region Monitoring Disabled Status)  
 
    .equ ICM_IER, ICM_BASE + 0x10 @ (Interrupt Enable) 
        .equ ICM_RHC_Shift, 0   @ bitWidth 4 (Region Hash Completed Interrupt Enable)  
        .equ ICM_RDM_Shift, 4   @ bitWidth 4 (Region Digest Mismatch Interrupt Enable)  
        .equ ICM_RBE_Shift, 8   @ bitWidth 4 (Region Bus Error Interrupt Enable)  
        .equ ICM_RWC_Shift, 12   @ bitWidth 4 (Region Wrap Condition detected Interrupt Enable)  
        .equ ICM_REC_Shift, 16   @ bitWidth 4 (Region End bit Condition Detected Interrupt Enable)  
        .equ ICM_RSU_Shift, 20   @ bitWidth 4 (Region Status Updated Interrupt Disable)  
        .equ ICM_URAD_Shift, 24   @ bitWidth 1 (Undefined Register Access Detection Interrupt Enable)  
 
    .equ ICM_IDR, ICM_BASE + 0x14 @ (Interrupt Disable) 
        .equ ICM_RHC_Shift, 0   @ bitWidth 4 (Region Hash Completed Interrupt Disable)  
        .equ ICM_RDM_Shift, 4   @ bitWidth 4 (Region Digest Mismatch Interrupt Disable)  
        .equ ICM_RBE_Shift, 8   @ bitWidth 4 (Region Bus Error Interrupt Disable)  
        .equ ICM_RWC_Shift, 12   @ bitWidth 4 (Region Wrap Condition Detected Interrupt Disable)  
        .equ ICM_REC_Shift, 16   @ bitWidth 4 (Region End bit Condition detected Interrupt Disable)  
        .equ ICM_RSU_Shift, 20   @ bitWidth 4 (Region Status Updated Interrupt Disable)  
        .equ ICM_URAD_Shift, 24   @ bitWidth 1 (Undefined Register Access Detection Interrupt Disable)  
 
    .equ ICM_IMR, ICM_BASE + 0x18 @ (Interrupt Mask) 
        .equ ICM_RHC_Shift, 0   @ bitWidth 4 (Region Hash Completed Interrupt Mask)  
        .equ ICM_RDM_Shift, 4   @ bitWidth 4 (Region Digest Mismatch Interrupt Mask)  
        .equ ICM_RBE_Shift, 8   @ bitWidth 4 (Region Bus Error Interrupt Mask)  
        .equ ICM_RWC_Shift, 12   @ bitWidth 4 (Region Wrap Condition Detected Interrupt Mask)  
        .equ ICM_REC_Shift, 16   @ bitWidth 4 (Region End bit Condition Detected Interrupt Mask)  
        .equ ICM_RSU_Shift, 20   @ bitWidth 4 (Region Status Updated Interrupt Mask)  
        .equ ICM_URAD_Shift, 24   @ bitWidth 1 (Undefined Register Access Detection Interrupt Mask)  
 
    .equ ICM_ISR, ICM_BASE + 0x1C @ (Interrupt Status) 
        .equ ICM_RHC_Shift, 0   @ bitWidth 4 (Region Hash Completed)  
        .equ ICM_RDM_Shift, 4   @ bitWidth 4 (Region Digest Mismatch)  
        .equ ICM_RBE_Shift, 8   @ bitWidth 4 (Region Bus Error)  
        .equ ICM_RWC_Shift, 12   @ bitWidth 4 (Region Wrap Condition Detected)  
        .equ ICM_REC_Shift, 16   @ bitWidth 4 (Region End bit Condition Detected)  
        .equ ICM_RSU_Shift, 20   @ bitWidth 4 (Region Status Updated Detected)  
        .equ ICM_URAD_Shift, 24   @ bitWidth 1 (Undefined Register Access Detection Status)  
 
    .equ ICM_UASR, ICM_BASE + 0x20 @ (Undefined Access Status) 
        .equ ICM_URAT_Shift, 0   @ bitWidth 3 (Undefined Register Access Trace)  
 
    .equ ICM_DSCR, ICM_BASE + 0x30 @ (Region Descriptor Area Start Address) 
        .equ ICM_DASA_Shift, 6   @ bitWidth 26 (Descriptor Area Start Address)  
 
    .equ ICM_HASH, ICM_BASE + 0x34 @ (Region Hash Area Start Address) 
        .equ ICM_HASA_Shift, 7   @ bitWidth 25 (Hash Area Start Address)  
 
    .equ ICM_UIHVAL[%s], ICM_BASE + 0x38 @ (User Initial Hash Value n) 
        .equ ICM_VAL_Shift, 0   @ bitWidth 32 (Initial Hash Value)  
 

@=========================== I2S ===========================@
.equ I2S_BASE, 0x43002800 @ (Inter-IC Sound Interface) 
    .equ I2S_CTRLA, I2S_BASE + 0x0 @ (Control A) 
        .equ I2S_SWRST_Shift, 0   @ bitWidth 1 (Software Reset)  
        .equ I2S_ENABLE_Shift, 1   @ bitWidth 1 (Enable)  
        .equ I2S_CKEN0_Shift, 2   @ bitWidth 1 (Clock Unit 0 Enable)  
        .equ I2S_CKEN1_Shift, 3   @ bitWidth 1 (Clock Unit 1 Enable)  
        .equ I2S_TXEN_Shift, 4   @ bitWidth 1 (Tx Serializer Enable)  
        .equ I2S_RXEN_Shift, 5   @ bitWidth 1 (Rx Serializer Enable)  
 
    .equ I2S_CLKCTRL[%s], I2S_BASE + 0x4 @ (Clock Unit n Control) 
        .equ I2S_SLOTSIZE_Shift, 0   @ bitWidth 2 (Slot Size)  
        .equ I2S_NBSLOTS_Shift, 2   @ bitWidth 3 (Number of Slots in Frame)  
        .equ I2S_FSWIDTH_Shift, 5   @ bitWidth 2 (Frame Sync Width)  
        .equ I2S_BITDELAY_Shift, 7   @ bitWidth 1 (Data Delay from Frame Sync)  
        .equ I2S_FSSEL_Shift, 8   @ bitWidth 1 (Frame Sync Select)  
        .equ I2S_FSINV_Shift, 9   @ bitWidth 1 (Frame Sync Invert)  
        .equ I2S_FSOUTINV_Shift, 10   @ bitWidth 1 (Frame Sync Output Invert)  
        .equ I2S_SCKSEL_Shift, 11   @ bitWidth 1 (Serial Clock Select)  
        .equ I2S_SCKOUTINV_Shift, 12   @ bitWidth 1 (Serial Clock Output Invert)  
        .equ I2S_MCKSEL_Shift, 13   @ bitWidth 1 (Master Clock Select)  
        .equ I2S_MCKEN_Shift, 14   @ bitWidth 1 (Master Clock Enable)  
        .equ I2S_MCKOUTINV_Shift, 15   @ bitWidth 1 (Master Clock Output Invert)  
        .equ I2S_MCKDIV_Shift, 16   @ bitWidth 6 (Master Clock Division Factor)  
        .equ I2S_MCKOUTDIV_Shift, 24   @ bitWidth 6 (Master Clock Output Division Factor)  
 
    .equ I2S_INTENCLR, I2S_BASE + 0xC @ (Interrupt Enable Clear) 
        .equ I2S_RXRDY0_Shift, 0   @ bitWidth 1 (Receive Ready 0 Interrupt Enable)  
        .equ I2S_RXRDY1_Shift, 1   @ bitWidth 1 (Receive Ready 1 Interrupt Enable)  
        .equ I2S_RXOR0_Shift, 4   @ bitWidth 1 (Receive Overrun 0 Interrupt Enable)  
        .equ I2S_RXOR1_Shift, 5   @ bitWidth 1 (Receive Overrun 1 Interrupt Enable)  
        .equ I2S_TXRDY0_Shift, 8   @ bitWidth 1 (Transmit Ready 0 Interrupt Enable)  
        .equ I2S_TXRDY1_Shift, 9   @ bitWidth 1 (Transmit Ready 1 Interrupt Enable)  
        .equ I2S_TXUR0_Shift, 12   @ bitWidth 1 (Transmit Underrun 0 Interrupt Enable)  
        .equ I2S_TXUR1_Shift, 13   @ bitWidth 1 (Transmit Underrun 1 Interrupt Enable)  
 
    .equ I2S_INTENSET, I2S_BASE + 0x10 @ (Interrupt Enable Set) 
        .equ I2S_RXRDY0_Shift, 0   @ bitWidth 1 (Receive Ready 0 Interrupt Enable)  
        .equ I2S_RXRDY1_Shift, 1   @ bitWidth 1 (Receive Ready 1 Interrupt Enable)  
        .equ I2S_RXOR0_Shift, 4   @ bitWidth 1 (Receive Overrun 0 Interrupt Enable)  
        .equ I2S_RXOR1_Shift, 5   @ bitWidth 1 (Receive Overrun 1 Interrupt Enable)  
        .equ I2S_TXRDY0_Shift, 8   @ bitWidth 1 (Transmit Ready 0 Interrupt Enable)  
        .equ I2S_TXRDY1_Shift, 9   @ bitWidth 1 (Transmit Ready 1 Interrupt Enable)  
        .equ I2S_TXUR0_Shift, 12   @ bitWidth 1 (Transmit Underrun 0 Interrupt Enable)  
        .equ I2S_TXUR1_Shift, 13   @ bitWidth 1 (Transmit Underrun 1 Interrupt Enable)  
 
    .equ I2S_INTFLAG, I2S_BASE + 0x14 @ (Interrupt Flag Status and Clear) 
        .equ I2S_RXRDY0_Shift, 0   @ bitWidth 1 (Receive Ready 0)  
        .equ I2S_RXRDY1_Shift, 1   @ bitWidth 1 (Receive Ready 1)  
        .equ I2S_RXOR0_Shift, 4   @ bitWidth 1 (Receive Overrun 0)  
        .equ I2S_RXOR1_Shift, 5   @ bitWidth 1 (Receive Overrun 1)  
        .equ I2S_TXRDY0_Shift, 8   @ bitWidth 1 (Transmit Ready 0)  
        .equ I2S_TXRDY1_Shift, 9   @ bitWidth 1 (Transmit Ready 1)  
        .equ I2S_TXUR0_Shift, 12   @ bitWidth 1 (Transmit Underrun 0)  
        .equ I2S_TXUR1_Shift, 13   @ bitWidth 1 (Transmit Underrun 1)  
 
    .equ I2S_SYNCBUSY, I2S_BASE + 0x18 @ (Synchronization Status) 
        .equ I2S_SWRST_Shift, 0   @ bitWidth 1 (Software Reset Synchronization Status)  
        .equ I2S_ENABLE_Shift, 1   @ bitWidth 1 (Enable Synchronization Status)  
        .equ I2S_CKEN0_Shift, 2   @ bitWidth 1 (Clock Unit 0 Enable Synchronization Status)  
        .equ I2S_CKEN1_Shift, 3   @ bitWidth 1 (Clock Unit 1 Enable Synchronization Status)  
        .equ I2S_TXEN_Shift, 4   @ bitWidth 1 (Tx Serializer Enable Synchronization Status)  
        .equ I2S_RXEN_Shift, 5   @ bitWidth 1 (Rx Serializer Enable Synchronization Status)  
        .equ I2S_TXDATA_Shift, 8   @ bitWidth 1 (Tx Data Synchronization Status)  
        .equ I2S_RXDATA_Shift, 9   @ bitWidth 1 (Rx Data Synchronization Status)  
 
    .equ I2S_TXCTRL, I2S_BASE + 0x20 @ (Tx Serializer Control) 
        .equ I2S_TXDEFAULT_Shift, 2   @ bitWidth 2 (Line Default Line when Slot Disabled)  
        .equ I2S_TXSAME_Shift, 4   @ bitWidth 1 (Transmit Data when Underrun)  
        .equ I2S_SLOTADJ_Shift, 7   @ bitWidth 1 (Data Slot Formatting Adjust)  
        .equ I2S_DATASIZE_Shift, 8   @ bitWidth 3 (Data Word Size)  
        .equ I2S_WORDADJ_Shift, 12   @ bitWidth 1 (Data Word Formatting Adjust)  
        .equ I2S_EXTEND_Shift, 13   @ bitWidth 2 (Data Formatting Bit Extension)  
        .equ I2S_BITREV_Shift, 15   @ bitWidth 1 (Data Formatting Bit Reverse)  
        .equ I2S_SLOTDIS0_Shift, 16   @ bitWidth 1 (Slot 0 Disabled for this Serializer)  
        .equ I2S_SLOTDIS1_Shift, 17   @ bitWidth 1 (Slot 1 Disabled for this Serializer)  
        .equ I2S_SLOTDIS2_Shift, 18   @ bitWidth 1 (Slot 2 Disabled for this Serializer)  
        .equ I2S_SLOTDIS3_Shift, 19   @ bitWidth 1 (Slot 3 Disabled for this Serializer)  
        .equ I2S_SLOTDIS4_Shift, 20   @ bitWidth 1 (Slot 4 Disabled for this Serializer)  
        .equ I2S_SLOTDIS5_Shift, 21   @ bitWidth 1 (Slot 5 Disabled for this Serializer)  
        .equ I2S_SLOTDIS6_Shift, 22   @ bitWidth 1 (Slot 6 Disabled for this Serializer)  
        .equ I2S_SLOTDIS7_Shift, 23   @ bitWidth 1 (Slot 7 Disabled for this Serializer)  
        .equ I2S_MONO_Shift, 24   @ bitWidth 1 (Mono Mode)  
        .equ I2S_DMA_Shift, 25   @ bitWidth 1 (Single or Multiple DMA Channels)  
 
    .equ I2S_RXCTRL, I2S_BASE + 0x24 @ (Rx Serializer Control) 
        .equ I2S_SERMODE_Shift, 0   @ bitWidth 2 (Serializer Mode)  
        .equ I2S_CLKSEL_Shift, 5   @ bitWidth 1 (Clock Unit Selection)  
        .equ I2S_SLOTADJ_Shift, 7   @ bitWidth 1 (Data Slot Formatting Adjust)  
        .equ I2S_DATASIZE_Shift, 8   @ bitWidth 3 (Data Word Size)  
        .equ I2S_WORDADJ_Shift, 12   @ bitWidth 1 (Data Word Formatting Adjust)  
        .equ I2S_EXTEND_Shift, 13   @ bitWidth 2 (Data Formatting Bit Extension)  
        .equ I2S_BITREV_Shift, 15   @ bitWidth 1 (Data Formatting Bit Reverse)  
        .equ I2S_SLOTDIS0_Shift, 16   @ bitWidth 1 (Slot 0 Disabled for this Serializer)  
        .equ I2S_SLOTDIS1_Shift, 17   @ bitWidth 1 (Slot 1 Disabled for this Serializer)  
        .equ I2S_SLOTDIS2_Shift, 18   @ bitWidth 1 (Slot 2 Disabled for this Serializer)  
        .equ I2S_SLOTDIS3_Shift, 19   @ bitWidth 1 (Slot 3 Disabled for this Serializer)  
        .equ I2S_SLOTDIS4_Shift, 20   @ bitWidth 1 (Slot 4 Disabled for this Serializer)  
        .equ I2S_SLOTDIS5_Shift, 21   @ bitWidth 1 (Slot 5 Disabled for this Serializer)  
        .equ I2S_SLOTDIS6_Shift, 22   @ bitWidth 1 (Slot 6 Disabled for this Serializer)  
        .equ I2S_SLOTDIS7_Shift, 23   @ bitWidth 1 (Slot 7 Disabled for this Serializer)  
        .equ I2S_MONO_Shift, 24   @ bitWidth 1 (Mono Mode)  
        .equ I2S_DMA_Shift, 25   @ bitWidth 1 (Single or Multiple DMA Channels)  
        .equ I2S_RXLOOP_Shift, 26   @ bitWidth 1 (Loop-back Test Mode)  
 
    .equ I2S_TXDATA, I2S_BASE + 0x30 @ (Tx Data) 
        .equ I2S_DATA_Shift, 0   @ bitWidth 32 (Sample Data)  
 
    .equ I2S_RXDATA, I2S_BASE + 0x34 @ (Rx Data) 
        .equ I2S_DATA_Shift, 0   @ bitWidth 32 (Sample Data)  
 

@=========================== MCLK ===========================@
.equ MCLK_BASE, 0x40000800 @ (Main Clock) 
