        .equ MCLK_CKRDY_Shift, 0   @ bitWidth 1 (Clock Ready)  
 
    .equ MCLK_HSDIV, MCLK_BASE + 0x4 @ (HS Clock Division) 
        .equ MCLK_DIV_Shift, 0   @ bitWidth 8 (CPU Clock Division Factor)  
 
    .equ MCLK_CPUDIV, MCLK_BASE + 0x5 @ (CPU Clock Division) 
