        .equ MCLK_DMAC__Shift, 9   @ bitWidth 1 (DMAC AHB Clock Mask)  
        .equ MCLK_USB__Shift, 10   @ bitWidth 1 (USB AHB Clock Mask)  
        .equ MCLK_PAC__Shift, 12   @ bitWidth 1 (PAC AHB Clock Mask)  
        .equ MCLK_QSPI__Shift, 13   @ bitWidth 1 (QSPI AHB Clock Mask)  
        .equ MCLK_GMAC__Shift, 14   @ bitWidth 1 (GMAC AHB Clock Mask)  
        .equ MCLK_SDHC0__Shift, 15   @ bitWidth 1 (SDHC0 AHB Clock Mask)  
        .equ MCLK_SDHC1__Shift, 16   @ bitWidth 1 (SDHC1 AHB Clock Mask)  
        .equ MCLK_CAN0__Shift, 17   @ bitWidth 1 (CAN0 AHB Clock Mask)  
        .equ MCLK_CAN1__Shift, 18   @ bitWidth 1 (CAN1 AHB Clock Mask)  
        .equ MCLK_ICM__Shift, 19   @ bitWidth 1 (ICM AHB Clock Mask)  
        .equ MCLK_PUKCC__Shift, 20   @ bitWidth 1 (PUKCC AHB Clock Mask)  
        .equ MCLK_QSPI_2X__Shift, 21   @ bitWidth 1 (QSPI_2X AHB Clock Mask)  
        .equ MCLK_NVMCTRL_SMEEPROM__Shift, 22   @ bitWidth 1 (NVMCTRL_SMEEPROM AHB Clock Mask)  
        .equ MCLK_NVMCTRL_CACHE__Shift, 23   @ bitWidth 1 (NVMCTRL_CACHE AHB Clock Mask)  
 
    .equ MCLK_APBAMASK, MCLK_BASE + 0x14 @ (APBA Mask) 
        .equ MCLK_PAC__Shift, 0   @ bitWidth 1 (PAC APB Clock Enable)  
