        .equ MCLK_MCLK__Shift, 2   @ bitWidth 1 (MCLK APB Clock Enable)  
        .equ MCLK_RSTC__Shift, 3   @ bitWidth 1 (RSTC APB Clock Enable)  
        .equ MCLK_OSCCTRL__Shift, 4   @ bitWidth 1 (OSCCTRL APB Clock Enable)  
        .equ MCLK_OSC32KCTRL__Shift, 5   @ bitWidth 1 (OSC32KCTRL APB Clock Enable)  
        .equ MCLK_SUPC__Shift, 6   @ bitWidth 1 (SUPC APB Clock Enable)  
        .equ MCLK_GCLK__Shift, 7   @ bitWidth 1 (GCLK APB Clock Enable)  
        .equ MCLK_WDT__Shift, 8   @ bitWidth 1 (WDT APB Clock Enable)  
        .equ MCLK_RTC__Shift, 9   @ bitWidth 1 (RTC APB Clock Enable)  
        .equ MCLK_EIC__Shift, 10   @ bitWidth 1 (EIC APB Clock Enable)  
        .equ MCLK_FREQM__Shift, 11   @ bitWidth 1 (FREQM APB Clock Enable)  
        .equ MCLK_SERCOM0__Shift, 12   @ bitWidth 1 (SERCOM0 APB Clock Enable)  
        .equ MCLK_SERCOM1__Shift, 13   @ bitWidth 1 (SERCOM1 APB Clock Enable)  
        .equ MCLK_TC0__Shift, 14   @ bitWidth 1 (TC0 APB Clock Enable)  
        .equ MCLK_TC1__Shift, 15   @ bitWidth 1 (TC1 APB Clock Enable)  
 
    .equ MCLK_APBBMASK, MCLK_BASE + 0x18 @ (APBB Mask) 
        .equ MCLK_USB__Shift, 0   @ bitWidth 1 (USB APB Clock Enable)  
        .equ MCLK_DSU__Shift, 1   @ bitWidth 1 (DSU APB Clock Enable)  
        .equ MCLK_NVMCTRL__Shift, 2   @ bitWidth 1 (NVMCTRL APB Clock Enable)  
        .equ MCLK_PORT__Shift, 4   @ bitWidth 1 (PORT APB Clock Enable)  
        .equ MCLK_EVSYS__Shift, 7   @ bitWidth 1 (EVSYS APB Clock Enable)  
        .equ MCLK_SERCOM2__Shift, 9   @ bitWidth 1 (SERCOM2 APB Clock Enable)  
        .equ MCLK_SERCOM3__Shift, 10   @ bitWidth 1 (SERCOM3 APB Clock Enable)  
        .equ MCLK_TCC0__Shift, 11   @ bitWidth 1 (TCC0 APB Clock Enable)  
        .equ MCLK_TCC1__Shift, 12   @ bitWidth 1 (TCC1 APB Clock Enable)  
        .equ MCLK_TC2__Shift, 13   @ bitWidth 1 (TC2 APB Clock Enable)  
        .equ MCLK_TC3__Shift, 14   @ bitWidth 1 (TC3 APB Clock Enable)  
        .equ MCLK_RAMECC__Shift, 16   @ bitWidth 1 (RAMECC APB Clock Enable)  
 
    .equ MCLK_APBCMASK, MCLK_BASE + 0x1C @ (APBC Mask) 
        .equ MCLK_GMAC__Shift, 2   @ bitWidth 1 (GMAC APB Clock Enable)  
        .equ MCLK_TCC2__Shift, 3   @ bitWidth 1 (TCC2 APB Clock Enable)  
        .equ MCLK_TCC3__Shift, 4   @ bitWidth 1 (TCC3 APB Clock Enable)  
        .equ MCLK_TC4__Shift, 5   @ bitWidth 1 (TC4 APB Clock Enable)  
        .equ MCLK_TC5__Shift, 6   @ bitWidth 1 (TC5 APB Clock Enable)  
        .equ MCLK_PDEC__Shift, 7   @ bitWidth 1 (PDEC APB Clock Enable)  
        .equ MCLK_AC__Shift, 8   @ bitWidth 1 (AC APB Clock Enable)  
        .equ MCLK_AES__Shift, 9   @ bitWidth 1 (AES APB Clock Enable)  
        .equ MCLK_TRNG__Shift, 10   @ bitWidth 1 (TRNG APB Clock Enable)  
        .equ MCLK_ICM__Shift, 11   @ bitWidth 1 (ICM APB Clock Enable)  
        .equ MCLK_QSPI__Shift, 13   @ bitWidth 1 (QSPI APB Clock Enable)  
        .equ MCLK_CCL__Shift, 14   @ bitWidth 1 (CCL APB Clock Enable)  
 
    .equ MCLK_APBDMASK, MCLK_BASE + 0x20 @ (APBD Mask) 
        .equ MCLK_SERCOM4__Shift, 0   @ bitWidth 1 (SERCOM4 APB Clock Enable)  
        .equ MCLK_SERCOM5__Shift, 1   @ bitWidth 1 (SERCOM5 APB Clock Enable)  
        .equ MCLK_SERCOM6__Shift, 2   @ bitWidth 1 (SERCOM6 APB Clock Enable)  
        .equ MCLK_SERCOM7__Shift, 3   @ bitWidth 1 (SERCOM7 APB Clock Enable)  
        .equ MCLK_TCC4__Shift, 4   @ bitWidth 1 (TCC4 APB Clock Enable)  
        .equ MCLK_TC6__Shift, 5   @ bitWidth 1 (TC6 APB Clock Enable)  
        .equ MCLK_TC7__Shift, 6   @ bitWidth 1 (TC7 APB Clock Enable)  
        .equ MCLK_ADC0__Shift, 7   @ bitWidth 1 (ADC0 APB Clock Enable)  
        .equ MCLK_ADC1__Shift, 8   @ bitWidth 1 (ADC1 APB Clock Enable)  
        .equ MCLK_DAC__Shift, 9   @ bitWidth 1 (DAC APB Clock Enable)  
        .equ MCLK_I2S__Shift, 10   @ bitWidth 1 (I2S APB Clock Enable)  
        .equ MCLK_PCC__Shift, 11   @ bitWidth 1 (PCC APB Clock Enable)  
 

@=========================== NVMCTRL ===========================@
.equ NVMCTRL_BASE, 0x41004000 @ (Non-Volatile Memory Controller) 
