        .equ OSCCTRL_XOSCFAIL0_Shift, 2   @ bitWidth 1 (XOSC 0 Clock Failure Detector Interrupt Enable)  
        .equ OSCCTRL_XOSCFAIL1_Shift, 3   @ bitWidth 1 (XOSC 1 Clock Failure Detector Interrupt Enable)  
        .equ OSCCTRL_DFLLRDY_Shift, 8   @ bitWidth 1 (DFLL Ready Interrupt Enable)  
