        .equ OSCCTRL_DFLLLCKC_Shift, 11   @ bitWidth 1 (DFLL Lock Coarse Interrupt Enable)  
        .equ OSCCTRL_DFLLRCS_Shift, 12   @ bitWidth 1 (DFLL Reference Clock Stopped Interrupt Enable)  
        .equ OSCCTRL_DPLL0LCKR_Shift, 16   @ bitWidth 1 (DPLL0 Lock Rise Interrupt Enable)  
        .equ OSCCTRL_DPLL0LCKF_Shift, 17   @ bitWidth 1 (DPLL0 Lock Fall Interrupt Enable)  
        .equ OSCCTRL_DPLL0LTO_Shift, 18   @ bitWidth 1 (DPLL0 Lock Timeout Interrupt Enable)  
        .equ OSCCTRL_DPLL0LDRTO_Shift, 19   @ bitWidth 1 (DPLL0 Loop Divider Ratio Update Complete Interrupt Enable)  
        .equ OSCCTRL_DPLL1LCKR_Shift, 24   @ bitWidth 1 (DPLL1 Lock Rise Interrupt Enable)  
        .equ OSCCTRL_DPLL1LCKF_Shift, 25   @ bitWidth 1 (DPLL1 Lock Fall Interrupt Enable)  
        .equ OSCCTRL_DPLL1LTO_Shift, 26   @ bitWidth 1 (DPLL1 Lock Timeout Interrupt Enable)  
        .equ OSCCTRL_DPLL1LDRTO_Shift, 27   @ bitWidth 1 (DPLL1 Loop Divider Ratio Update Complete Interrupt Enable)  
 
    .equ OSCCTRL_INTFLAG, OSCCTRL_BASE + 0xC @ (Interrupt Flag Status and Clear) 
        .equ OSCCTRL_XOSCRDY0_Shift, 0   @ bitWidth 1 (XOSC 0 Ready)  
