        .equ OSCCTRL_DPLL1LDRTO_Shift, 27   @ bitWidth 1 (DPLL1 Loop Divider Ratio Update Complete)  
 
    .equ OSCCTRL_XOSCCTRL[%s], OSCCTRL_BASE + 0x14 @ (External Multipurpose Crystal Oscillator Control) 
        .equ OSCCTRL_ENABLE_Shift, 1   @ bitWidth 1 (Oscillator Enable)  
