        .equ OSCCTRL_RUNSTDBY_Shift, 6   @ bitWidth 1 (Run in Standby)  
        .equ OSCCTRL_ONDEMAND_Shift, 7   @ bitWidth 1 (On Demand Control)  
        .equ OSCCTRL_LOWBUFGAIN_Shift, 8   @ bitWidth 1 (Low Buffer Gain Enable)  
        .equ OSCCTRL_IPTAT_Shift, 9   @ bitWidth 2 (Oscillator Current Reference)  
        .equ OSCCTRL_IMULT_Shift, 11   @ bitWidth 4 (Oscillator Current Multiplier)  
        .equ OSCCTRL_ENALC_Shift, 15   @ bitWidth 1 (Automatic Loop Control Enable)  
        .equ OSCCTRL_CFDEN_Shift, 16   @ bitWidth 1 (Clock Failure Detector Enable)  
        .equ OSCCTRL_SWBEN_Shift, 17   @ bitWidth 1 (Xosc Clock Switch Enable)  
        .equ OSCCTRL_STARTUP_Shift, 20   @ bitWidth 4 (Start-Up Time)  
        .equ OSCCTRL_CFDPRESC_Shift, 24   @ bitWidth 4 (Clock Failure Detector Prescaler)  
 
    .equ OSCCTRL_DFLLCTRLA, OSCCTRL_BASE + 0x1C @ (DFLL48M Control A) 
        .equ OSCCTRL_ENABLE_Shift, 1   @ bitWidth 1 (DFLL Enable)  
        .equ OSCCTRL_RUNSTDBY_Shift, 6   @ bitWidth 1 (Run in Standby)  
        .equ OSCCTRL_ONDEMAND_Shift, 7   @ bitWidth 1 (On Demand Control)  
 
    .equ OSCCTRL_DFLLCTRLB, OSCCTRL_BASE + 0x20 @ (DFLL48M Control B) 
        .equ OSCCTRL_MODE_Shift, 0   @ bitWidth 1 (Operating Mode Selection)  
        .equ OSCCTRL_STABLE_Shift, 1   @ bitWidth 1 (Stable DFLL Frequency)  
