        .equ TCC2_CC4_Shift, 12   @ bitWidth 1 (Compare Channel 4 Busy)  
        .equ TCC2_CC5_Shift, 13   @ bitWidth 1 (Compare Channel 5 Busy)  
 
    .equ TCC2_FCTRLA, TCC2_BASE + 0xC @ (Recoverable Fault A Configuration) 
        .equ TCC2_SRC_Shift, 0   @ bitWidth 2 (Fault A Source)  
