    .equ TCC3_CCBUF[%s], TCC3_BASE + 0x70 @ (Compare and Capture Buffer) 
        .equ TCC3_CCBUF_Shift, 0   @ bitWidth 24 (Channel Compare/Capture Buffer Value)  
 
    .equ TCC3_CCBUF_DITH4_MODE[%s], TCC3_BASE + 0x70 @ (Compare and Capture Buffer) 
