    .equ ITM_PORT_WORD_MODE[%s], ITM_BASE + 0x0 @ (ITM Stimulus Port Registers) 
        .equ ITM_PORT_Shift, 0   @ bitWidth 32 ()  
 
    .equ ITM_TER, ITM_BASE + 0xE00 @ (ITM Trace Enable Register) 
 
    .equ ITM_TPR, ITM_BASE + 0xE40 @ (ITM Trace Privilege Register) 
        .equ ITM_PRIVMASK_Shift, 0   @ bitWidth 4 ()  
 
    .equ ITM_TCR, ITM_BASE + 0xE80 @ (ITM Trace Control Register) 
        .equ ITM_ITMENA_Shift, 0   @ bitWidth 1 ()  
        .equ ITM_TSENA_Shift, 1   @ bitWidth 1 ()  
        .equ ITM_SYNCENA_Shift, 2   @ bitWidth 1 ()  
        .equ ITM_DWTENA_Shift, 3   @ bitWidth 1 ()  
        .equ ITM_SWOENA_Shift, 4   @ bitWidth 1 ()  
        .equ ITM_STALLENA_Shift, 5   @ bitWidth 1 ()  
        .equ ITM_TSPrescale_Shift, 8   @ bitWidth 2 ()  
        .equ ITM_GTSFREQ_Shift, 10   @ bitWidth 2 ()  
        .equ ITM_TraceBusID_Shift, 16   @ bitWidth 7 ()  
        .equ ITM_BUSY_Shift, 23   @ bitWidth 1 ()  
 
    .equ ITM_IWR, ITM_BASE + 0xEF8 @ (ITM Integration Write Register) 
        .equ ITM_ATVALIDM_Shift, 0   @ bitWidth 1 ()  
 
    .equ ITM_IRR, ITM_BASE + 0xEFC @ (ITM Integration Read Register) 
        .equ ITM_ATREADYM_Shift, 0   @ bitWidth 1 ()  
 
    .equ ITM_PID4, ITM_BASE + 0xFD0 @ (ITM Peripheral Identification Register #4) 
 
    .equ ITM_PID5, ITM_BASE + 0xFD4 @ (ITM Peripheral Identification Register #5) 
 
    .equ ITM_PID6, ITM_BASE + 0xFD8 @ (ITM Peripheral Identification Register #6) 
 
    .equ ITM_PID7, ITM_BASE + 0xFDC @ (ITM Peripheral Identification Register #7) 
 
    .equ ITM_PID0, ITM_BASE + 0xFE0 @ (ITM Peripheral Identification Register #0) 
 
    .equ ITM_PID1, ITM_BASE + 0xFE4 @ (ITM Peripheral Identification Register #1) 
 
    .equ ITM_PID2, ITM_BASE + 0xFE8 @ (ITM Peripheral Identification Register #2) 
 
    .equ ITM_PID3, ITM_BASE + 0xFEC @ (ITM Peripheral Identification Register #3) 
 
    .equ ITM_CID0, ITM_BASE + 0xFF0 @ (ITM Component Identification Register #0) 
 
    .equ ITM_CID1, ITM_BASE + 0xFF4 @ (ITM Component Identification Register #1) 
 
    .equ ITM_CID2, ITM_BASE + 0xFF8 @ (ITM Component Identification Register #2) 
 
    .equ ITM_CID3, ITM_BASE + 0xFFC @ (ITM Component Identification Register #3) 
 

@=========================== MPU ===========================@
.equ MPU_BASE, 0xE000ED90 @ (Memory Protection Unit) 
    .equ MPU_TYPE, MPU_BASE + 0x0 @ (MPU Type Register) 
        .equ MPU_SEPARATE_Shift, 0   @ bitWidth 1 (Separate instruction and Data Memory MapsRegions)  
        .equ MPU_DREGION_Shift, 8   @ bitWidth 8 (Number of Data Regions)  
        .equ MPU_IREGION_Shift, 16   @ bitWidth 8 (Number of Instruction Regions)  
 
    .equ MPU_CTRL, MPU_BASE + 0x4 @ (MPU Control Register) 
        .equ MPU_ENABLE_Shift, 0   @ bitWidth 1 (MPU Enable)  
        .equ MPU_HFNMIENA_Shift, 1   @ bitWidth 1 (Enable Hard Fault and NMI handlers)  
        .equ MPU_PRIVDEFENA_Shift, 2   @ bitWidth 1 (Enables privileged software access to default memory map)  
 
    .equ MPU_RNR, MPU_BASE + 0x8 @ (MPU Region Number Register) 
        .equ MPU_REGION_Shift, 0   @ bitWidth 8 (Region referenced by RBAR and RASR)  
 
    .equ MPU_RBAR, MPU_BASE + 0xC @ (MPU Region Base Address Register) 
        .equ MPU_REGION_Shift, 0   @ bitWidth 4 (Region number)  
        .equ MPU_VALID_Shift, 4   @ bitWidth 1 (Region number valid)  
        .equ MPU_ADDR_Shift, 5   @ bitWidth 27 (Region base address)  
 
    .equ MPU_RASR, MPU_BASE + 0x10 @ (MPU Region Attribute and Size Register) 
        .equ MPU_ENABLE_Shift, 0   @ bitWidth 1 (Region Enable)  
        .equ MPU_SIZE_Shift, 1   @ bitWidth 1 (Region Size)  
        .equ MPU_SRD_Shift, 8   @ bitWidth 8 (Sub-region disable)  
        .equ MPU_B_Shift, 16   @ bitWidth 1 (Bufferable bit)  
        .equ MPU_C_Shift, 17   @ bitWidth 1 (Cacheable bit)  
        .equ MPU_S_Shift, 18   @ bitWidth 1 (Shareable bit)  
        .equ MPU_TEX_Shift, 19   @ bitWidth 3 (TEX bit)  
        .equ MPU_AP_Shift, 24   @ bitWidth 3 (Access Permission)  
        .equ MPU_XN_Shift, 28   @ bitWidth 1 (Execute Never Attribute)  
 
    .equ MPU_RBAR_A1, MPU_BASE + 0x14 @ (MPU Alias 1 Region Base Address Register) 
        .equ MPU_REGION_Shift, 0   @ bitWidth 4 (Region number)  
        .equ MPU_VALID_Shift, 4   @ bitWidth 1 (Region number valid)  
        .equ MPU_ADDR_Shift, 5   @ bitWidth 27 (Region base address)  
 
    .equ MPU_RASR_A1, MPU_BASE + 0x18 @ (MPU Alias 1 Region Attribute and Size Register) 
        .equ MPU_ENABLE_Shift, 0   @ bitWidth 1 (Region Enable)  
        .equ MPU_SIZE_Shift, 1   @ bitWidth 1 (Region Size)  
        .equ MPU_SRD_Shift, 8   @ bitWidth 8 (Sub-region disable)  
        .equ MPU_B_Shift, 16   @ bitWidth 1 (Bufferable bit)  
        .equ MPU_C_Shift, 17   @ bitWidth 1 (Cacheable bit)  
        .equ MPU_S_Shift, 18   @ bitWidth 1 (Shareable bit)  
        .equ MPU_TEX_Shift, 19   @ bitWidth 3 (TEX bit)  
        .equ MPU_AP_Shift, 24   @ bitWidth 3 (Access Permission)  
        .equ MPU_XN_Shift, 28   @ bitWidth 1 (Execute Never Attribute)  
 
    .equ MPU_RBAR_A2, MPU_BASE + 0x1C @ (MPU Alias 2 Region Base Address Register) 
        .equ MPU_REGION_Shift, 0   @ bitWidth 4 (Region number)  
        .equ MPU_VALID_Shift, 4   @ bitWidth 1 (Region number valid)  
        .equ MPU_ADDR_Shift, 5   @ bitWidth 27 (Region base address)  
 
    .equ MPU_RASR_A2, MPU_BASE + 0x20 @ (MPU Alias 2 Region Attribute and Size Register) 
        .equ MPU_ENABLE_Shift, 0   @ bitWidth 1 (Region Enable)  
        .equ MPU_SIZE_Shift, 1   @ bitWidth 1 (Region Size)  
        .equ MPU_SRD_Shift, 8   @ bitWidth 8 (Sub-region disable)  
        .equ MPU_B_Shift, 16   @ bitWidth 1 (Bufferable bit)  
        .equ MPU_C_Shift, 17   @ bitWidth 1 (Cacheable bit)  
        .equ MPU_S_Shift, 18   @ bitWidth 1 (Shareable bit)  
        .equ MPU_TEX_Shift, 19   @ bitWidth 3 (TEX bit)  
        .equ MPU_AP_Shift, 24   @ bitWidth 3 (Access Permission)  
        .equ MPU_XN_Shift, 28   @ bitWidth 1 (Execute Never Attribute)  
 
    .equ MPU_RBAR_A3, MPU_BASE + 0x24 @ (MPU Alias 3 Region Base Address Register) 
        .equ MPU_REGION_Shift, 0   @ bitWidth 4 (Region number)  
        .equ MPU_VALID_Shift, 4   @ bitWidth 1 (Region number valid)  
        .equ MPU_ADDR_Shift, 5   @ bitWidth 27 (Region base address)  
 
    .equ MPU_RASR_A3, MPU_BASE + 0x28 @ (MPU Alias 3 Region Attribute and Size Register) 
        .equ MPU_ENABLE_Shift, 0   @ bitWidth 1 (Region Enable)  
        .equ MPU_SIZE_Shift, 1   @ bitWidth 1 (Region Size)  
        .equ MPU_SRD_Shift, 8   @ bitWidth 8 (Sub-region disable)  
        .equ MPU_B_Shift, 16   @ bitWidth 1 (Bufferable bit)  
        .equ MPU_C_Shift, 17   @ bitWidth 1 (Cacheable bit)  
        .equ MPU_S_Shift, 18   @ bitWidth 1 (Shareable bit)  
        .equ MPU_TEX_Shift, 19   @ bitWidth 3 (TEX bit)  
        .equ MPU_AP_Shift, 24   @ bitWidth 3 (Access Permission)  
        .equ MPU_XN_Shift, 28   @ bitWidth 1 (Execute Never Attribute)  
 

@=========================== NVIC ===========================@
.equ NVIC_BASE, 0xE000E100 @ (Nested Vectored Interrupt Controller) 
    .equ NVIC_ISER[%s], NVIC_BASE + 0x0 @ (Interrupt Set Enable Register) 
        .equ NVIC_SETENA_Shift, 0   @ bitWidth 32 (Interrupt set enable bits)  
 
    .equ NVIC_ICER[%s], NVIC_BASE + 0x80 @ (Interrupt Clear Enable Register) 
        .equ NVIC_CLRENA_Shift, 0   @ bitWidth 32 (Interrupt clear-enable bits)  
 
    .equ NVIC_ISPR[%s], NVIC_BASE + 0x100 @ (Interrupt Set Pending Register) 
        .equ NVIC_SETPEND_Shift, 0   @ bitWidth 32 (Interrupt set-pending bits)  
 
    .equ NVIC_ICPR[%s], NVIC_BASE + 0x180 @ (Interrupt Clear Pending Register) 
        .equ NVIC_CLRPEND_Shift, 0   @ bitWidth 32 (Interrupt clear-pending bits)  
 
    .equ NVIC_IABR[%s], NVIC_BASE + 0x200 @ (Interrupt Active Bit Register) 
        .equ NVIC_ACTIVE_Shift, 0   @ bitWidth 32 (Interrupt active bits)  
 
    .equ NVIC_IP[%s], NVIC_BASE + 0x300 @ (Interrupt Priority Register n) 
        .equ NVIC_PRI0_Shift, 0   @ bitWidth 3 (Priority of interrupt n)  
 
    .equ NVIC_STIR, NVIC_BASE + 0xE00 @ (Software Trigger Interrupt Register) 
        .equ NVIC_INTID_Shift, 0   @ bitWidth 9 (Interrupt ID to trigger)  
 

@=========================== SysTick ===========================@
.equ SysTick_BASE, 0xE000E010 @ (System timer) 
    .equ SysTick_CSR, SysTick_BASE + 0x0 @ (SysTick Control and Status Register) 
        .equ SysTick_ENABLE_Shift, 0   @ bitWidth 1 (SysTick Counter Enable)  
        .equ SysTick_TICKINT_Shift, 1   @ bitWidth 1 (SysTick Exception Request Enable)  
        .equ SysTick_CLKSOURCE_Shift, 2   @ bitWidth 1 (Clock Source 0=external, 1=processor)  
        .equ SysTick_COUNTFLAG_Shift, 16   @ bitWidth 1 (Timer counted to 0 since last read of register)  
 
    .equ SysTick_RVR, SysTick_BASE + 0x4 @ (SysTick Reload Value Register) 
        .equ SysTick_RELOAD_Shift, 0   @ bitWidth 24 (Value to load into the SysTick Current Value Register when the counter reaches 0)  
 
    .equ SysTick_CVR, SysTick_BASE + 0x8 @ (SysTick Current Value Register) 
        .equ SysTick_CURRENT_Shift, 0   @ bitWidth 24 (Current value at the time the register is accessed)  
 
    .equ SysTick_CALIB, SysTick_BASE + 0xC @ (SysTick Calibration Value Register) 
        .equ SysTick_TENMS_Shift, 0   @ bitWidth 24 (Reload value to use for 10ms timing)  
        .equ SysTick_SKEW_Shift, 30   @ bitWidth 1 (TENMS is rounded from non-integer ratio)  
        .equ SysTick_NOREF_Shift, 31   @ bitWidth 1 (No Separate Reference Clock)  
 

@=========================== SystemControl ===========================@
.equ SystemControl_BASE, 0xE000E000 @ (System Control Registers) 
    .equ SystemControl_ICTR, SystemControl_BASE + 0x4 @ (Interrupt Controller Type Register) 
        .equ SystemControl_INTLINESNUM_Shift, 0   @ bitWidth 4 ()  
 
    .equ SystemControl_ACTLR, SystemControl_BASE + 0x8 @ (Auxiliary Control Register) 
        .equ SystemControl_DISMCYCINT_Shift, 0   @ bitWidth 1 (Disable interruption of LDM/STM instructions)  
        .equ SystemControl_DISDEFWBUF_Shift, 1   @ bitWidth 1 (Disable wruite buffer use during default memory map accesses)  
        .equ SystemControl_DISFOLD_Shift, 2   @ bitWidth 1 (Disable IT folding)  
        .equ SystemControl_DISFPCA_Shift, 8   @ bitWidth 1 (Disable automatic update of CONTROL.FPCA)  
        .equ SystemControl_DISOOFP_Shift, 9   @ bitWidth 1 (Disable out-of-order FP instructions)  
 
    .equ SystemControl_CPUID, SystemControl_BASE + 0xD00 @ (CPUID Base Register) 
        .equ SystemControl_REVISION_Shift, 0   @ bitWidth 4 (Processor revision number)  
        .equ SystemControl_PARTNO_Shift, 4   @ bitWidth 12 (Process Part Number, 0xC24=Cortex-M4)  
        .equ SystemControl_CONSTANT_Shift, 16   @ bitWidth 4 (Constant)  
        .equ SystemControl_VARIANT_Shift, 20   @ bitWidth 4 (Variant number)  
        .equ SystemControl_IMPLEMENTER_Shift, 24   @ bitWidth 8 (Implementer code, 0x41=ARM)  
 
    .equ SystemControl_ICSR, SystemControl_BASE + 0xD04 @ (Interrupt Control and State Register) 
        .equ SystemControl_VECTACTIVE_Shift, 0   @ bitWidth 9 (Active exception number)  
        .equ SystemControl_RETTOBASE_Shift, 11   @ bitWidth 1 (No preempted active exceptions to execute)  
        .equ SystemControl_VECTPENDING_Shift, 12   @ bitWidth 6 (Exception number of the highest priority pending enabled exception)  
        .equ SystemControl_ISRPENDING_Shift, 22   @ bitWidth 1 (Interrupt pending flag)  
        .equ SystemControl_ISRPREEMPT_Shift, 23   @ bitWidth 1 (Debug only)  
        .equ SystemControl_PENDSTCLR_Shift, 25   @ bitWidth 1 (SysTick clear-pending bit)  
        .equ SystemControl_PENDSTSET_Shift, 26   @ bitWidth 1 (SysTick set-pending bit)  
        .equ SystemControl_PENDSVCLR_Shift, 27   @ bitWidth 1 (PendSV clear-pending bit)  
        .equ SystemControl_PENDSVSET_Shift, 28   @ bitWidth 1 (PendSV set-pending bit)  
        .equ SystemControl_NMIPENDSET_Shift, 31   @ bitWidth 1 (NMI set-pending bit)  
 
    .equ SystemControl_VTOR, SystemControl_BASE + 0xD08 @ (Vector Table Offset Register) 
        .equ SystemControl_TBLOFF_Shift, 7   @ bitWidth 25 (Vector table base offset)  
 
    .equ SystemControl_AIRCR, SystemControl_BASE + 0xD0C @ (Application Interrupt and Reset Control Register) 
        .equ SystemControl_VECTRESET_Shift, 0   @ bitWidth 1 (Must write 0)  
        .equ SystemControl_VECTCLRACTIVE_Shift, 1   @ bitWidth 1 (Must write 0)  
        .equ SystemControl_SYSRESETREQ_Shift, 2   @ bitWidth 1 (System Reset Request)  
        .equ SystemControl_PRIGROUP_Shift, 8   @ bitWidth 3 (Interrupt priority grouping)  
        .equ SystemControl_ENDIANNESS_Shift, 15   @ bitWidth 1 (Data endianness, 0=little, 1=big)  
        .equ SystemControl_VECTKEY_Shift, 16   @ bitWidth 16 (Register key)  
 
    .equ SystemControl_SCR, SystemControl_BASE + 0xD10 @ (System Control Register) 
        .equ SystemControl_SLEEPONEXIT_Shift, 1   @ bitWidth 1 (Sleep-on-exit on handler return)  
        .equ SystemControl_SLEEPDEEP_Shift, 2   @ bitWidth 1 (Deep Sleep used as low power mode)  
        .equ SystemControl_SEVONPEND_Shift, 4   @ bitWidth 1 (Send Event on Pending bit)  
 
    .equ SystemControl_CCR, SystemControl_BASE + 0xD14 @ (Configuration and Control Register) 
        .equ SystemControl_NONBASETHRDENA_Shift, 0   @ bitWidth 1 (Indicates how processor enters Thread mode)  
        .equ SystemControl_USERSETMPEND_Shift, 1   @ bitWidth 1 (Enables unprivileged software access to STIR register)  
        .equ SystemControl_UNALIGN_TRP_Shift, 3   @ bitWidth 1 (Enables unaligned access traps)  
        .equ SystemControl_DIV_0_TRP_Shift, 4   @ bitWidth 1 (Enables divide by 0 trap)  
        .equ SystemControl_BFHFNMIGN_Shift, 8   @ bitWidth 1 (Ignore LDM/STM BusFault for -1/-2 priority handlers)  
        .equ SystemControl_STKALIGN_Shift, 9   @ bitWidth 1 (Indicates stack alignment on exception entry)  
 
    .equ SystemControl_SHPR1, SystemControl_BASE + 0xD18 @ (System Handler Priority Register 1) 
        .equ SystemControl_PRI_4_Shift, 0   @ bitWidth 8 (Priority of system handler 4, MemManage)  
        .equ SystemControl_PRI_5_Shift, 8   @ bitWidth 8 (Priority of system handler 5, BusFault)  
        .equ SystemControl_PRI_6_Shift, 16   @ bitWidth 8 (Priority of system handler 6, UsageFault)  
 
    .equ SystemControl_SHPR2, SystemControl_BASE + 0xD1C @ (System Handler Priority Register 2) 
        .equ SystemControl_PRI_11_Shift, 24   @ bitWidth 8 (Priority of system handler 11, SVCall)  
 
    .equ SystemControl_SHPR3, SystemControl_BASE + 0xD20 @ (System Handler Priority Register 3) 
        .equ SystemControl_PRI_14_Shift, 16   @ bitWidth 8 (Priority of system handler 14, PendSV)  
        .equ SystemControl_PRI_15_Shift, 24   @ bitWidth 8 (Priority of system handler 15, SysTick exception)  
 
    .equ SystemControl_SHCSR, SystemControl_BASE + 0xD24 @ (System Handler Control and State Register) 
        .equ SystemControl_MEMFAULTACT_Shift, 0   @ bitWidth 1 (MemManage exception active bit)  
        .equ SystemControl_BUSFAULTACT_Shift, 1   @ bitWidth 1 (BusFault exception active bit)  
        .equ SystemControl_USGFAULTACT_Shift, 3   @ bitWidth 1 (UsageFault exception active bit)  
        .equ SystemControl_SVCALLACT_Shift, 7   @ bitWidth 1 (SVCall active bit)  
        .equ SystemControl_MONITORACT_Shift, 8   @ bitWidth 1 (DebugMonitor exception active bit)  
        .equ SystemControl_PENDSVACT_Shift, 10   @ bitWidth 1 (PendSV exception active bit)  
        .equ SystemControl_SYSTICKACT_Shift, 11   @ bitWidth 1 (SysTick exception active bit)  
        .equ SystemControl_USGFAULTPENDED_Shift, 12   @ bitWidth 1 (UsageFault exception pending bit)  
        .equ SystemControl_MEMFAULTPENDED_Shift, 13   @ bitWidth 1 (MemManage exception pending bit)  
        .equ SystemControl_BUSFAULTPENDED_Shift, 14   @ bitWidth 1 (BusFault exception pending bit)  
        .equ SystemControl_SVCALLPENDED_Shift, 15   @ bitWidth 1 (SVCall pending bit)  
        .equ SystemControl_MEMFAULTENA_Shift, 16   @ bitWidth 1 (MemManage enable bit)  
        .equ SystemControl_BUSFAULTENA_Shift, 17   @ bitWidth 1 (BusFault enable bit)  
        .equ SystemControl_USGFAULTENA_Shift, 18   @ bitWidth 1 (UsageFault enable bit)  
 
    .equ SystemControl_CFSR, SystemControl_BASE + 0xD28 @ (Configurable Fault Status Register) 
        .equ SystemControl_IACCVIOL_Shift, 0   @ bitWidth 1 (Instruction access violation)  
        .equ SystemControl_DACCVIOL_Shift, 1   @ bitWidth 1 (Data access violation)  
        .equ SystemControl_MUNSTKERR_Shift, 3   @ bitWidth 1 (MemManage Fault on unstacking for exception return)  
        .equ SystemControl_MSTKERR_Shift, 4   @ bitWidth 1 (MemManage Fault on stacking for exception entry)  
        .equ SystemControl_MLSPERR_Shift, 5   @ bitWidth 1 (MemManager Fault occured during FP lazy state preservation)  
        .equ SystemControl_MMARVALID_Shift, 7   @ bitWidth 1 (MemManage Fault Address Register valid)  
        .equ SystemControl_IBUSERR_Shift, 8   @ bitWidth 1 (Instruction bus error)  
        .equ SystemControl_PRECISERR_Shift, 9   @ bitWidth 1 (Precise data bus error)  
        .equ SystemControl_IMPRECISERR_Shift, 10   @ bitWidth 1 (Imprecise data bus error)  
        .equ SystemControl_UNSTKERR_Shift, 11   @ bitWidth 1 (BusFault on unstacking for exception return)  
        .equ SystemControl_STKERR_Shift, 12   @ bitWidth 1 (BusFault on stacking for exception entry)  
        .equ SystemControl_LSPERR_Shift, 13   @ bitWidth 1 (BusFault occured during FP lazy state preservation)  
        .equ SystemControl_BFARVALID_Shift, 15   @ bitWidth 1 (BusFault Address Register valid)  
        .equ SystemControl_UNDEFINSTR_Shift, 16   @ bitWidth 1 (Undefined instruction UsageFault)  
        .equ SystemControl_INVSTATE_Shift, 17   @ bitWidth 1 (Invalid state UsageFault)  
        .equ SystemControl_INVPC_Shift, 18   @ bitWidth 1 (Invalid PC load UsageFault)  
        .equ SystemControl_NOCP_Shift, 19   @ bitWidth 1 (No coprocessor UsageFault)  
        .equ SystemControl_UNALIGNED_Shift, 24   @ bitWidth 1 (Unaligned access UsageFault)  
        .equ SystemControl_DIVBYZERO_Shift, 25   @ bitWidth 1 (Divide by zero UsageFault)  
 
    .equ SystemControl_HFSR, SystemControl_BASE + 0xD2C @ (HardFault Status Register) 
        .equ SystemControl_VECTTBL_Shift, 1   @ bitWidth 1 (BusFault on a Vector Table read during exception processing)  
        .equ SystemControl_FORCED_Shift, 30   @ bitWidth 1 (Forced Hard Fault)  
        .equ SystemControl_DEBUGEVT_Shift, 31   @ bitWidth 1 (Debug: always write 0)  
 
    .equ SystemControl_DFSR, SystemControl_BASE + 0xD30 @ (Debug Fault Status Register) 
        .equ SystemControl_HALTED_Shift, 0   @ bitWidth 1 ()  
        .equ SystemControl_BKPT_Shift, 1   @ bitWidth 1 ()  
        .equ SystemControl_DWTTRAP_Shift, 2   @ bitWidth 1 ()  
        .equ SystemControl_VCATCH_Shift, 3   @ bitWidth 1 ()  
        .equ SystemControl_EXTERNAL_Shift, 4   @ bitWidth 1 ()  
 
    .equ SystemControl_MMFAR, SystemControl_BASE + 0xD34 @ (MemManage Fault Address Register) 
        .equ SystemControl_ADDRESS_Shift, 0   @ bitWidth 32 (Address that generated the MemManage fault)  
 
    .equ SystemControl_BFAR, SystemControl_BASE + 0xD38 @ (BusFault Address Register) 
        .equ SystemControl_ADDRESS_Shift, 0   @ bitWidth 32 (Address that generated the BusFault)  
 
    .equ SystemControl_AFSR, SystemControl_BASE + 0xD3C @ (Auxiliary Fault Status Register) 
        .equ SystemControl_IMPDEF_Shift, 0   @ bitWidth 32 (AUXFAULT input signals)  
 
    .equ SystemControl_PFR[%s], SystemControl_BASE + 0xD40 @ (Processor Feature Register) 
 
    .equ SystemControl_DFR, SystemControl_BASE + 0xD48 @ (Debug Feature Register) 
 
    .equ SystemControl_ADR, SystemControl_BASE + 0xD4C @ (Auxiliary Feature Register) 
 
    .equ SystemControl_MMFR[%s], SystemControl_BASE + 0xD50 @ (Memory Model Feature Register) 
 
    .equ SystemControl_ISAR[%s], SystemControl_BASE + 0xD60 @ (Instruction Set Attributes Register) 
 
    .equ SystemControl_CPACR, SystemControl_BASE + 0xD88 @ (Coprocessor Access Control Register) 
        .equ SystemControl_CP10_Shift, 20   @ bitWidth 2 (Access privileges for coprocessor 10)  
        .equ SystemControl_CP11_Shift, 22   @ bitWidth 2 (Access privileges for coprocessor 11)  
 

@=========================== TPIU ===========================@
.equ TPIU_BASE, 0xE0040000 @ (Trace Port Interface Unit) 
    .equ TPIU_SSPSR, TPIU_BASE + 0x0 @ (Supported Parallel Port Size Register) 
 
    .equ TPIU_CSPSR, TPIU_BASE + 0x4 @ (Current Parallel Port Size Register) 
 
    .equ TPIU_ACPR, TPIU_BASE + 0x10 @ (Asynchronous Clock Prescaler Register) 
        .equ TPIU_PRESCALER_Shift, 0   @ bitWidth 13 ()  
 
    .equ TPIU_SPPR, TPIU_BASE + 0xF0 @ (Selected Pin Protocol Register) 
        .equ TPIU_TXMODE_Shift, 0   @ bitWidth 2 ()  
 
    .equ TPIU_FFSR, TPIU_BASE + 0x300 @ (Formatter and Flush Status Register) 
        .equ TPIU_FlInProg_Shift, 0   @ bitWidth 1 ()  
        .equ TPIU_FtStopped_Shift, 1   @ bitWidth 1 ()  
        .equ TPIU_TCPresent_Shift, 2   @ bitWidth 1 ()  
        .equ TPIU_FtNonStop_Shift, 3   @ bitWidth 1 ()  
 
    .equ TPIU_FFCR, TPIU_BASE + 0x304 @ (Formatter and Flush Control Register) 
        .equ TPIU_EnFCont_Shift, 1   @ bitWidth 1 ()  
        .equ TPIU_TrigIn_Shift, 8   @ bitWidth 1 ()  
 
    .equ TPIU_FSCR, TPIU_BASE + 0x308 @ (Formatter Synchronization Counter Register) 
 
    .equ TPIU_TRIGGER, TPIU_BASE + 0xEE8 @ (TRIGGER) 
        .equ TPIU_TRIGGER_Shift, 0   @ bitWidth 1 ()  
 
    .equ TPIU_FIFO0, TPIU_BASE + 0xEEC @ (Integration ETM Data) 
        .equ TPIU_ETM0_Shift, 0   @ bitWidth 8 ()  
        .equ TPIU_ETM1_Shift, 8   @ bitWidth 8 ()  
        .equ TPIU_ETM2_Shift, 16   @ bitWidth 8 ()  
        .equ TPIU_ETM_bytecount_Shift, 24   @ bitWidth 2 ()  
        .equ TPIU_ETM_ATVALID_Shift, 26   @ bitWidth 1 ()  
        .equ TPIU_ITM_bytecount_Shift, 27   @ bitWidth 2 ()  
        .equ TPIU_ITM_ATVALID_Shift, 29   @ bitWidth 1 ()  
 
    .equ TPIU_ITATBCTR2, TPIU_BASE + 0xEF0 @ (ITATBCTR2) 
        .equ TPIU_ATREADY_Shift, 0   @ bitWidth 1 ()  
 
    .equ TPIU_ITATBCTR0, TPIU_BASE + 0xEF8 @ (ITATBCTR0) 
        .equ TPIU_ATREADY_Shift, 0   @ bitWidth 1 ()  
 
    .equ TPIU_FIFO1, TPIU_BASE + 0xEFC @ (Integration ITM Data) 
        .equ TPIU_ITM0_Shift, 0   @ bitWidth 8 ()  
        .equ TPIU_ITM1_Shift, 8   @ bitWidth 8 ()  
        .equ TPIU_ITM2_Shift, 16   @ bitWidth 8 ()  
        .equ TPIU_ETM_bytecount_Shift, 24   @ bitWidth 2 ()  
        .equ TPIU_ETM_ATVALID_Shift, 26   @ bitWidth 1 ()  
        .equ TPIU_ITM_bytecount_Shift, 27   @ bitWidth 2 ()  
        .equ TPIU_ITM_ATVALID_Shift, 29   @ bitWidth 1 ()  
 
    .equ TPIU_ITCTRL, TPIU_BASE + 0xF00 @ (Integration Mode Control) 
        .equ TPIU_Mode_Shift, 0   @ bitWidth 1 ()  
 
    .equ TPIU_CLAIMSET, TPIU_BASE + 0xFA0 @ (Claim tag set) 
 
    .equ TPIU_CLAIMCLR, TPIU_BASE + 0xFA4 @ (Claim tag clear) 
 
    .equ TPIU_DEVID, TPIU_BASE + 0xFC8 @ (TPIU_DEVID) 
        .equ TPIU_NrTraceInput_Shift, 0   @ bitWidth 1 ()  
        .equ TPIU_AsynClkIn_Shift, 5   @ bitWidth 1 ()  
        .equ TPIU_MinBufSz_Shift, 6   @ bitWidth 3 ()  
        .equ TPIU_PTINVALID_Shift, 9   @ bitWidth 1 ()  
        .equ TPIU_MANCVALID_Shift, 10   @ bitWidth 1 ()  
        .equ TPIU_NRZVALID_Shift, 11   @ bitWidth 1 ()  
 
    .equ TPIU_DEVTYPE, TPIU_BASE + 0xFCC @ (TPIU_DEVTYPE) 
        .equ TPIU_SubType_Shift, 0   @ bitWidth 4 ()  
        .equ TPIU_MajorType_Shift, 4   @ bitWidth 4 ()  
 
